CREATE TABLE portal_read_model.baby_growth_entry(id uuid PRIMARY KEY,measured_at timestamptz NOT NULL,weight_g integer CHECK(weight_g BETWEEN 300 AND 40000),length_cm numeric(5,2) CHECK(length_cm BETWEEN 20 AND 130),head_cm numeric(5,2) CHECK(head_cm BETWEEN 20 AND 65),provider text NOT NULL DEFAULT '' CHECK(char_length(provider)<=160),notes text NOT NULL DEFAULT '' CHECK(char_length(notes)<=1000),created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),CHECK(weight_g IS NOT NULL OR length_cm IS NOT NULL OR head_cm IS NOT NULL));
CREATE INDEX baby_growth_time_idx ON portal_read_model.baby_growth_entry(measured_at DESC);
CREATE TABLE portal_read_model.baby_milestone(id uuid PRIMARY KEY,observed_at date NOT NULL,domain text NOT NULL CHECK(domain IN('movement','communication','social','cognitive','other')),title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 160),notes text NOT NULL DEFAULT '' CHECK(char_length(notes)<=1000),media_url text NOT NULL DEFAULT '' CHECK(char_length(media_url)<=500),question_for_clinician boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()));
CREATE INDEX baby_milestone_time_idx ON portal_read_model.baby_milestone(observed_at DESC);
ALTER TABLE portal_read_model.baby_growth_entry ENABLE ROW LEVEL SECURITY;ALTER TABLE portal_read_model.baby_growth_entry FORCE ROW LEVEL SECURITY;ALTER TABLE portal_read_model.baby_milestone ENABLE ROW LEVEL SECURITY;ALTER TABLE portal_read_model.baby_milestone FORCE ROW LEVEL SECURITY;
REVOKE ALL ON portal_read_model.baby_growth_entry,portal_read_model.baby_milestone FROM PUBLIC,anon,authenticated;GRANT SELECT,INSERT ON portal_read_model.baby_growth_entry,portal_read_model.baby_milestone TO service_role;
CREATE POLICY baby_growth_deny_clients ON portal_read_model.baby_growth_entry FOR ALL TO anon,authenticated USING(false) WITH CHECK(false);CREATE POLICY baby_milestone_deny_clients ON portal_read_model.baby_milestone FOR ALL TO anon,authenticated USING(false) WITH CHECK(false);
CREATE OR REPLACE FUNCTION public.embe_list_baby_development() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $f$ SELECT jsonb_build_object('growth',COALESCE((SELECT jsonb_agg(to_jsonb(g) ORDER BY measured_at DESC) FROM portal_read_model.baby_growth_entry g),'[]'::jsonb),'milestones',COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY observed_at DESC) FROM portal_read_model.baby_milestone m),'[]'::jsonb));$f$;
CREATE OR REPLACE FUNCTION public.embe_add_baby_growth(p_id uuid,p_measured_at timestamptz,p_weight_g integer,p_length_cm numeric,p_head_cm numeric,p_provider text,p_notes text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path='' AS $f$ INSERT INTO portal_read_model.baby_growth_entry(id,measured_at,weight_g,length_cm,head_cm,provider,notes) VALUES(p_id,p_measured_at,p_weight_g,p_length_cm,p_head_cm,trim(p_provider),trim(p_notes));$f$;
CREATE OR REPLACE FUNCTION public.embe_add_baby_milestone(p_id uuid,p_observed_at date,p_domain text,p_title text,p_notes text,p_media_url text,p_question boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path='' AS $f$ INSERT INTO portal_read_model.baby_milestone(id,observed_at,domain,title,notes,media_url,question_for_clinician) VALUES(p_id,p_observed_at,p_domain,trim(p_title),trim(p_notes),trim(p_media_url),p_question);$f$;
REVOKE ALL ON FUNCTION public.embe_list_baby_development(),public.embe_add_baby_growth(uuid,timestamptz,integer,numeric,numeric,text,text),public.embe_add_baby_milestone(uuid,date,text,text,text,text,boolean) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.embe_list_baby_development(),public.embe_add_baby_growth(uuid,timestamptz,integer,numeric,numeric,text,text),public.embe_add_baby_milestone(uuid,date,text,text,text,text,boolean) TO service_role;
